-- RecipeDB: every profession recipe in WoW Forever (Data/Recipes.lua,
-- generated by tools/recipes.js from the game's own data tables via
-- wago.tools), plus search over names, the window's groups and materials.
--
-- Only IDs are bundled. Names, icons and quality come from the player's own
-- game at runtime (async, through CraftIndex's name cache), so they're
-- always right and in the player's language. A recipe the running client
-- says doesn't exist (C_Spell.DoesSpellExist) is hidden.
local _, SK = ...

local DB = SK:NewModule("RecipeDB")
local Compat = SK.Compat

DB.MIN_QUERY = 3
DB.MAX_RESULTS = 300
DB.REQUESTS_PER_SEARCH = 200 -- name loads asked for per search (the rest follow as names arrive)

local byID, all, byProf
local catNames = {}

-- Entry: { recipeID, skillLine, itemID, cat, reag = "item:count,...",
--   min, low, high, ups } (skill-up range from Forever's data, v0.4.4),
--   yield = items made per craft (v0.4.6, 0 when it makes no item)
local function index()
	if byID then return end
	byID, all, byProf = {}, {}, {}
	for skillLine, list in pairs(SK.Data.RECIPE_LIST or {}) do
		byProf[skillLine] = {}
		for _, e in ipairs(list) do
			local r = { recipeID = e[1], skillLine = skillLine, itemID = e[2] or 0, cat = e[3], reag = e[4] or "",
				min = e[5] or 0, low = e[6] or 0, high = e[7] or 0, ups = e[8] or 0, yield = e[9] or 0 }
			if not byID[r.recipeID] then
				byID[r.recipeID] = r
				all[#all + 1] = r
				byProf[skillLine][#byProf[skillLine] + 1] = r
			end
		end
	end
end

function DB.Reset() byID, all, byProf, catNames = nil, nil, nil, {} end

-- The recipe item that teaches it (pattern, plan, formula...) and the skill
-- needed to learn it, from Forever's data (v0.5.0); nil when there's none.
function DB.RecipeItem(recipeID)
	local e = SK.Data.RECIPE_ITEMS and SK.Data.RECIPE_ITEMS[recipeID]
	if e then return e[1], e[2] end
end

function DB.Count() index(); return #all end
function DB.Get(recipeID) index(); return byID[recipeID] end

-- Recipes of one profession (or all), skipping ones this client doesn't have.
function DB.List(skillLine)
	index()
	local src = skillLine and (byProf[skillLine] or {}) or all
	local out = {}
	for _, r in ipairs(src) do
		if Compat.SpellExists(r.recipeID) ~= false then out[#out + 1] = r end
	end
	return out
end

-- { { itemID, qty } } from the bundled data.
function DB.Reagents(recipeID)
	local r = DB.Get(recipeID)
	local out = {}
	if not r then return out end
	for id, n in r.reag:gmatch("(%d+):(%d+)") do out[#out + 1] = { itemID = tonumber(id), qty = tonumber(n) } end
	return out
end

-- The window's group name ("Camping"), from the game when it can say
-- (localised), else the bundled English name.
function DB.CategoryName(cat)
	if not cat then return nil end
	if catNames[cat] == nil then
		catNames[cat] = Compat.CategoryInfo(cat) or false
	end
	if catNames[cat] then return catNames[cat] end
	local c = SK.Data.RECIPE_CATS and SK.Data.RECIPE_CATS[cat]
	return c and c[1] or nil
end

---------------------------------------------------------------------------
-- Skill-up colours (v0.4.4). From Forever's own data (SkillLineAbility via
-- tools/recipes.js): yellow from TrivialSkillLineRankLow, grey from
-- TrivialSkillLineRankHigh, green from halfway between (the profession
-- window's rule), orange below yellow. Forever's numbers differ from Classic
-- (Gray Woolen Shirt: yellow 90, grey 110). MinSkillLineRank is 1 for almost
-- every recipe in Forever, so it is NOT when you can learn a recipe (the
-- trainer or recipe decides; not in the data): only learned recipes get a
-- "for you" colour. Checked against the player's own window during scans
-- (DB.CheckColour, /sr debug).
---------------------------------------------------------------------------
DB.COLOURS = { "orange", "yellow", "green", "grey" }
-- Blizzard's Enum.TradeskillRelativeDifficulty: Optimal, Medium, Easy, Trivial.
DB.CHECK_VERSION = 2
DB.GAME_COLOUR = { [0] = "orange", [1] = "yellow", [2] = "green", [3] = "grey" }

-- { orange, yellow, green, grey, ups } or nil when the data has no range.
function DB.Range(recipeID)
	local r = DB.Get(recipeID)
	if not r or r.high <= 0 or r.low <= 0 or r.high < r.low then return nil end -- missing or inconsistent data
	return { orange = r.min, yellow = r.low, green = math.floor((r.low + r.high) / 2), grey = r.high,
		ups = r.ups > 0 and r.ups or 1 }
end

-- The colour a recipe is at `skill`: "orange" | "yellow" | "green" | "grey",
-- or nil if unknown. Below the orange start counts as orange (you can't learn
-- it yet; the trainer or recipe decides when).
function DB.ColourAt(recipeID, skill)
	local g = DB.Range(recipeID)
	if not g or type(skill) ~= "number" then return nil end
	if skill >= g.grey then return "grey" end
	if skill >= g.green then return "green" end
	if skill >= g.yellow then return "yellow" end
	return "orange"
end

-- Skill points until it turns grey (0 when grey).
function DB.PointsLeft(recipeID, skill)
	local g = DB.Range(recipeID)
	if not g or type(skill) ~= "number" then return nil end
	return math.max(0, g.grey - skill)
end

-- Compare our colour with the game's (from the open profession window).
-- Kept per game build in SK.DB.colourCheck; shown in /sr debug.
DB.CHECK_EXAMPLES = 5
function DB.CheckColour(recipeID, skill, gameDifficulty)
	local game = DB.GAME_COLOUR[gameDifficulty]
	local ours = DB.ColourAt(recipeID, skill)
	if not game or not ours then return nil end
	if type(skill) ~= "number" or skill < 1 then return nil end
	local build = tostring(Compat.BuildInfo().build or "?")
	local c = SK.DB.colourCheck
	-- Version 2 (v0.4.7) starts the count again: version 1 also compared at skill 0.
	if c.build ~= build or c.v ~= DB.CHECK_VERSION then
		c.build, c.v, c.match, c.differ, c.examples = build, DB.CHECK_VERSION, 0, 0, {}
	end
	if game == ours then
		c.match = c.match + 1
	else
		c.differ = c.differ + 1
		if #c.examples < DB.CHECK_EXAMPLES then
			c.examples[#c.examples + 1] = { recipe = recipeID, skill = skill, game = game, ours = ours }
		end
	end
	return game == ours
end

-- Levelling helper: the LEARNED recipes of one profession that still give
-- skill-ups at `skill`, best first (orange, yellow, green), then the soonest
-- to turn grey. `known` = { [recipeID] = true }. Unlearned recipes are left
-- out: when a trainer or recipe teaches them isn't in Forever's data.
-- Returns rows { recipeID, itemID, skillLine, colour, left, range, known }.
local COLOUR_ORDER = { orange = 1, yellow = 2, green = 3, grey = 4 }
function DB.SkillUps(skillLine, skill, known)
	local out = {}
	known = known or {}
	for _, r in ipairs(DB.List(skillLine)) do
		local colour = known[r.recipeID] and DB.ColourAt(r.recipeID, skill)
		if colour and colour ~= "grey" then
			out[#out + 1] = { recipeID = r.recipeID, itemID = r.itemID, skillLine = skillLine, colour = colour,
				left = DB.PointsLeft(r.recipeID, skill), range = DB.Range(r.recipeID), known = known[r.recipeID] == true }
		end
	end
	table.sort(out, function(a, b)
		if a.known ~= b.known then return a.known end
		if a.colour ~= b.colour then return COLOUR_ORDER[a.colour] < COLOUR_ORDER[b.colour] end
		if a.left ~= b.left then return a.left < b.left end
		return a.recipeID < b.recipeID
	end)
	return out
end

-- The logged-in character's skill in a profession, or nil.
function DB.MySkill(skillLine)
	local own = SK.Profile and SK.Profile:Own()
	local p = own and own.profs and own.profs[skillLine]
	return p and type(p.rank) == "number" and p.rank or nil
end

-- Has the logged-in character learned this recipe (as last scanned)?
function DB.IKnow(recipeID, skillLine)
	local own = SK.Profile and SK.Profile:Own()
	local list = own and own.recipes and own.recipes[skillLine]
	return list ~= nil and list[recipeID] ~= nil
end

function DB.WowheadURL(recipeID, itemID)
	if itemID and itemID > 0 then return "https://www.wowhead.com/forever/item=" .. itemID end
	return "https://www.wowhead.com/forever/spell=" .. recipeID
end

---------------------------------------------------------------------------
-- Search
---------------------------------------------------------------------------
local function lower(s) return s and s:lower() or nil end

-- Which part matched: "name", "group" or "material" (with the material's name).
local function matchOf(r, q, CI)
	local name = (r.itemID > 0 and CI.ItemName(r.itemID)) or CI.SpellName(r.recipeID)
	if name and lower(name):find(q, 1, true) then return "name", nil, name end
	local spell = CI.SpellName(r.recipeID)
	if spell and spell ~= name and lower(spell):find(q, 1, true) then return "name", nil, name or spell end
	local group = DB.CategoryName(r.cat)
	if group and lower(group):find(q, 1, true) then return "group", group, name end
	for id in r.reag:gmatch("(%d+):%d+") do
		local m = CI.ItemName(tonumber(id))
		if m and lower(m):find(q, 1, true) then return "material", m, name end
	end
	return nil, nil, name
end

-- query: text (at least MIN_QUERY letters, unless a profession is picked);
-- skillLine: nil = every profession. Returns rows, state, loading:
--   state "short" (type more) or "ok"; loading = recipes whose name hasn't
--   arrived yet (they may match once it does).
-- Row: { recipeID, itemID, skillLine, cat, name, group, count, fav, match, matched }
function DB.Search(query, skillLine, craftIndex)
	local CI = SK.CraftIndex
	craftIndex = craftIndex or CI:Get()
	query = lower((query or ""):gsub("^%s+", ""):gsub("%s+$", ""))
	if #query < DB.MIN_QUERY and not skillLine then return {}, "short", 0 end
	CI.SetBudget(DB.REQUESTS_PER_SEARCH)
	local rows, loading = {}, 0
	for _, r in ipairs(DB.List(skillLine)) do
		local match, matched, name
		if query == "" then
			name = (r.itemID > 0 and CI.ItemName(r.itemID)) or CI.SpellName(r.recipeID)
			match = "all"
		else
			match, matched, name = matchOf(r, query, CI)
		end
		if not name then loading = loading + 1 end
		if match then
			local known = craftIndex.recipes[r.recipeID]
			rows[#rows + 1] = { recipeID = r.recipeID, itemID = r.itemID, skillLine = r.skillLine, cat = r.cat,
				name = name or "...", group = DB.CategoryName(r.cat) or "", count = known and #known.crafters or 0,
				fav = SK.Favourites.IsRecipe(r.recipeID), match = match, matched = matched }
		end
	end
	CI.SetBudget(nil)
	table.sort(rows, function(a, b)
		if (a.name == "...") ~= (b.name == "...") then return b.name == "..." end
		if a.name ~= b.name then return a.name < b.name end
		return a.recipeID < b.recipeID
	end)
	for i = #rows, DB.MAX_RESULTS + 1, -1 do rows[i] = nil end
	return rows, "ok", loading
end
